INSERT INTO `notification` VALUES (2, 12, 1, 'COMMENT_POST', 'POST', 168, '评论了你的帖子：这个就是火影忍者手游的logo吧，太帅了', 1, '2026-09-04 14:47:07');
INSERT INTO `post` VALUES (1, 1, 1, '原神新手入门指南', '欢迎来到提瓦特大陆！本指南将帮助你快速上手原神世界。从基础操作到角色养成，从资源分配到任务优先级，全方位带你开启冒险之旅！', 15, 20, 156, '2026-05-28 11:40:28', NULL, 0, 0);
