INSERT INTO `post` VALUES (150, 5, 1, '蒙德纪念品商店买什么好', '风之印和岩之印优先兑换什么最划算？蒙德纪念品商店购买推荐！', 42, 29, 45, '2026-04-10 03:41:08', NULL, 0, 0);
INSERT INTO `post` VALUES (151, 1, 7, '火影忍者新手入门指南', '欢迎来到火影忍者论坛！这里是火之国忍者的聚集地。作为刚入坑的萌新，这份指南非常适合你！', 4, 6, 2, '2026-05-28 19:40:16', NULL, 0, 0);
INSERT INTO `post` VALUES (152, 1, 7, '宇智波一族的秘密', '写轮眼的进化之路，从三勾玉到万花筒。深入剖析宇智波一族的历史和秘密！', 46, 0, 3, '2026-04-15 04:25:18', NULL, 0, 0);
INSERT INTO `post` VALUES (153, 2, 7, '鸣人的成长历程', '从吊车尾到拯救世界的英雄，鸣人的故事令人感动！', 33, 1, 1, '2026-04-17 00:13:10', NULL, 0, 0);
INSERT INTO `post` VALUES (154, 2, 7, '晓组织成员实力排名', '佩恩、鼬、长门...谁才是最强的？客观分析晓组织成员的实力排名！', 39, 20, 1, '2026-05-05 00:57:20', NULL, 0, 0);
INSERT INTO `post` VALUES (155, 1, 7, '忍术结印大全', '各种忍术的结印方式详解。成为忍术大师的第一步！', 49, 33, 1, '2026-05-28 17:14:36', NULL, 0, 0);
INSERT INTO `post` VALUES (156, 3, 7, '五影会谈背后的阴谋', '第四次忍界大战的导火索。五影会谈背后隐藏着怎样的阴谋？', 40, 3, 2, '2026-06-01 00:28:28', NULL, 0, 0);
INSERT INTO `post` VALUES (157, 3, 7, '我爱罗的砂之守护', '一尾守鹤与人柱力的羁绊。我爱罗从人柱力到风影的蜕变！', 8, 13, 1, '2026-04-07 11:45:55', NULL, 0, 0);
INSERT INTO `post` VALUES (158, 4, 7, '卡卡西的写轮眼', '带土与卡卡西之间的故事。卡卡西的写轮眼是怎么来的？', 22, 10, 1, '2026-04-29 22:31:38', NULL, 0, 0);
INSERT INTO `post` VALUES (159, 4, 7, '纲手的医疗忍术', '木叶三忍之一的传奇女忍者。纲手作为五代火影，医疗忍术的巅峰！', 44, 8, 1, '2026-05-31 18:27:51', NULL, 0, 0);
INSERT INTO `post` VALUES (160, 5, 7, '自来也豪杰物语', '永不放弃的火之意志。自来也的一生充满传奇色彩，真正的豪杰！', 16, 8, 1, '2026-05-01 13:51:44', NULL, 0, 0);
INSERT INTO `post` VALUES (161, 12, 1, '欢迎新人', '欢迎欢迎欢迎！', 18, 19, 0, '2026-04-29 03:02:35', NULL, 0, 0);
INSERT INTO `post` VALUES (162, 1, 7, '你好', '你们好！', 46, 18, 2, '2026-05-16 10:45:08', NULL, 0, 0);
INSERT INTO `post` VALUES (163, 1, 7, '每天分享一次', '这是六月五号的分享，剧场版活动在火影手游出现了！', 24, 1, 3, '2026-06-05 17:47:41', NULL, 0, 0);
INSERT INTO `post` VALUES (164, 12, 7, '鸣人和佐助', '鸣人是第七代火影，佐助是宇智波一族的', 13, 0, 0, '2026-06-05 21:51:01', NULL, 0, 0);
INSERT INTO `post` VALUES (166, 13, 1, '1234', '欢迎大家观看视频！！', 3, 0, 0, '2026-06-19 19:37:48', NULL, 0, 0);
INSERT INTO `post` VALUES (167, 12, 12, '九月s是谁', '九月S是晓朱鼬', 3, 1, 0, '2026-09-03 19:47:26', NULL, 0, 0);
INSERT INTO `post` VALUES (168, 12, 13, '火影图片', 'logo', 15, 2, 2, '2026-09-04 10:13:05', NULL, 1, 1);
INSERT INTO `post` VALUES (169, 1, 14, '铁甲尖兵开荒思路：护甲流还是力量流？', '开荒期能量紧张，很多新手纠结先拿防御牌还是攻击牌。建议第一章优先补齐2-3张稳定格挡保证血线，第二章再转向力量/免疫类核心卡。护甲流上限低但稳，力量流吃装备配合，按手感选。', 18, 4, 0, '2026-09-04 11:00:00', NULL, 0, 0);
INSERT INTO `post` VALUES (170, 2, 14, '观者觉醒形态输出循环拆解', '观者伤害来自姿态切换：攻击姿态吃暴击、防御姿态叠反伤回能。推荐循环——先切攻击姿态打爆发，残血前切防御姿态回能并触发反伤。注意「重身」卡能复制上一张攻击牌，是核心爆发点。', 22, 6, 0, '2026-09-04 11:20:00', NULL, 0, 0);
INSERT INTO `post` VALUES (171, 3, 15, '毒流派核心卡取舍与 combo 连携', '毒流核心是「催化」+「腐化之触」，靠叠毒层数而非攻击力。优先拿0费小毒卡铺层，配合「剧毒云雾」群体挂毒。避坑：别拿加攻击力的卡，毒伤不吃攻击加成，纯浪费卡位。', 31, 9, 0, '2026-09-04 14:05:00', NULL, 0, 0);
INSERT INTO `post` VALUES (172, 4, 15, '一回合爆发流卡组构筑思路', '爆发流靠「能量核心」遗物+「戏法」复制关键牌，单回合塞满手牌打空能量。核心是「重击」系列高费高伤卡，配合「时间扭曲」多抽。注意手牌上限，留过牌卡防卡死。', 15, 3, 0, '2026-09-04 15:40:00', NULL, 0, 0);
INSERT INTO `post` VALUES (173, 12, 16, '必拿遗物 TOP5 与新手避坑指南', '①能量核心（每回合+1能量，质变）；②焚血符（受伤换能量）；③抽牌鱼（每回合多抽）；④护符（首伤免疫）；⑤存钱罐（金子换属性）。避坑：前期别拿纯装饰遗物，优先功能性。', 48, 12, 0, '2026-09-04 16:10:00', NULL, 0, 0);
INSERT INTO `post` VALUES (174, 5, 17, '无限塔高层通关心得交流', '高层怪血量爆炸，拖回合必死。核心思路：前几层攒齐成型卡组，中期靠遗物滚雪球，boss层留好爆发。该删的卡尽早删，卡组越薄越强。欢迎分享你的通关层数！', 10, 2, 0, '2026-09-04 17:30:00', NULL, 0, 0);
INSERT INTO `post` VALUES (175, 1, 19, 'S35 赛季打野梯度：李白韩信还能玩吗？', '新版本野区改动后，李白前期节奏变慢，韩信依旧吃操作。个人体感 T1 是赵云、澜，T2 是李白、韩信。想问下高分段打野都怎么选？', 42, 8, 0, '2026-09-04 12:00:00', NULL, 0, 0);
INSERT INTO `post` VALUES (176, 2, 19, '对抗路对线细节：亚瑟 vs 花木兰怎么打', '花木兰双剑期消耗很强，亚瑟要卡她二技能 CD 再反打；重剑期不要硬拼，等她切回双剑再上。出装建议早出反甲。', 31, 5, 0, '2026-09-04 13:20:00', NULL, 0, 0);
INSERT INTO `post` VALUES (177, 12, 18, '王者峡谷有哪些冷门但强势的英雄？', '说说你们压箱底的冷门英雄，我先来：对抗路夏洛特、打野云中君、辅助鲁班大师，胜率都还不错。', 58, 12, 0, '2026-09-04 14:10:00', NULL, 0, 0);
INSERT INTO `post` VALUES (178, 3, 20, '新版本装备调整解读：打野刀改动影响', '打野刀合成更平滑，前期续航提升，对赵云、铠这类战士打野是加强，法师打野影响不大。', 27, 4, 0, '2026-09-04 15:00:00', NULL, 0, 0);
INSERT INTO `post` VALUES (179, 5, 21, '找固定队，星耀段位，晚上在线', '主玩射手和辅助，晚上 8-11 点在线，找稳定队友一起上分，要求心态好能开麦。', 23, 2, 0, '2026-09-04 16:30:00', NULL, 0, 0);
INSERT INTO `post` VALUES (180, 4, 18, '辅助玩家该不该出输出装？', '个人认为辅助优先功能性和保命，输出交给 C 位；但顺风时补一件输出装能加快节奏。你们怎么看？', 25, 7, 1, '2026-09-04 17:10:00', NULL, 0, 0);
INSERT INTO `post` VALUES (181, 1, 22, '欢迎来到无畏契约！', '这里是无畏契约大舞台，灯光已就位，心跳已拉满！不管你是刚入坑的萌新，还是久经沙场的老兵，只要你敢秀操作，这里就是你发光发热的战场。枪林弹雨里谁才是真英雄？战术博弈中谁能笑到最后？别犹豫，别低调，叫上你的队友，一起来点燃这场属于无畏者的狂欢吧！', 14, 1, 0, '2026-09-05 15:56:02', NULL, 0, 0);
