INSERT INTO `wzry_hero` VALUES (1, '亚瑟', '圣骑士', '战士', '对抗路', 2, 5888, 288, '亚', NULL, '被动·圣光守护：每 3 秒回复生命，脱战回复翻倍\n一技能·誓约之盾：加速减伤，下次普攻额外伤害并沉默\n二技能·回旋打击：旋转持续范围伤害\n三技能·圣剑裁决：跃起砸地范围击飞，残血敌人斩杀', '抵抗之靴、暗影战斧、极寒风暴、不死鸟之眼、破军、贤者的庇护', '异变 + 鹰眼 + 隐匿（物理穿透流）', '新手首选，靠被动续航赖线；团战一技能沉默后排，大招留人斩杀。', '2026-09-04 14:19:35');
INSERT INTO `wzry_hero` VALUES (2, '花木兰', '传说之刃', '战士', '对抗路', 7, 18888, 588, '花', NULL, '被动·长城巡守者：双剑/重剑形态切换，重剑免伤提升\n一技能·空裂斩：突进并标记，可二段位移\n二技能·回旋之刃：旋转击退并减速\n三技能·绽放之刃：切换重剑，范围伤害并免伤', '抵抗之靴、暗影战斧、泣血之刃、无尽战刃、破军、名刀·司命', '异变 + 鹰眼 + 隐匿', '双剑打一套切重剑免伤撤离，一技能二段可穿墙追击或逃生。', '2026-09-04 14:19:35');
INSERT INTO `wzry_hero` VALUES (3, '铠', '破灭之刃', '战士', '对抗路', 5, 13888, 488, '铠', NULL, '被动·修罗之魂：普攻附带额外魔法伤害\n一技能·极刃风暴：向前挥砍并减速\n二技能·八荒归元：向指定方向突进并强化下次普攻\n三技能·不灭魔躯：变身提升攻速与免伤，持续期间强化普攻', '抵抗之靴、暗影战斧、极寒风暴、不死鸟之眼、破军、贤者的庇护', '异变 + 鹰眼 + 隐匿', '开大后正面刚，二技能突进留人；注意大招真空期别硬上。', '2026-09-04 14:19:35');
INSERT INTO `wzry_hero` VALUES (4, '赵云', '苍天翔龙', '战士', '打野', 6, 18888, 688, '赵', NULL, '被动·龙鸣：生命越低减伤越高\n一技能·惊雷之龙：突进并击飞\n二技能·破云之龙：横扫范围伤害\n三技能·天翔之龙：跃起落地范围击飞并感电', '追击刀锋、抵抗之靴、暗影战斧、极寒风暴、破军、名刀·司命', '异变 + 鹰眼 + 隐匿', '残血时被动减伤极高，可卖血反打；大招落地秒接一技能连控。', '2026-09-04 14:19:35');
INSERT INTO `wzry_hero` VALUES (5, '孙悟空', '齐天大圣', '刺客', '打野', 6, 18888, 688, '孙', NULL, '被动·大圣神威：释放技能后强化下次普攻\n一技能·护身法咒：格挡一次技能并短暂无敌\n二技能·斗战冲锋：突进并可借目标二次位移\n三技能·如意金箍：范围击飞并标记，普攻标记目标造成额外伤害', '追击刀锋、急速战靴、无尽战刃、宗师之力、泣血之刃、破军', '无双 + 鹰眼 + 兽痕（暴击流）', '技能穿插普攻打爆发；一技能可挡关键控制，二技能借兵线位移。', '2026-09-04 14:19:35');
INSERT INTO `wzry_hero` VALUES (6, '李白', '青莲剑仙', '刺客', '打野', 8, 18888, 688, '李', NULL, '被动·侠客行：普攻叠加剑气，四下后解锁青莲剑歌\n一技能·将进酒：突进并眩晕，可返回原点\n二技能·神来之笔：范围减速并破甲\n三技能·青莲剑歌：多段范围伤害，期间不可被选中', '追击刀锋、急速战靴、泣血之刃、无尽战刃、破军、名刀·司命', '无双 + 鹰眼 + 兽痕', '靠野怪或小兵叠被动入场，大招期间无法被选中，可用来躲关键技能。', '2026-09-04 14:19:35');
INSERT INTO `wzry_hero` VALUES (7, '韩信', '国士无双', '刺客', '打野', 7, 18888, 688, '韩', NULL, '被动·杀意之枪：第四次普攻挑飞并回血\n一技能·无情冲锋：长距离位移\n二技能·背水一战：反向位移并强化下次普攻\n三技能·国士无双：范围多段伤害并击飞', '追击刀锋、急速战靴、暗影战斧、无尽战刃、泣血之刃、破军', '异变 + 鹰眼 + 隐匿', '位移多、机动强，主打开野经济与分带牵制；团战切后排要干脆。', '2026-09-04 14:19:35');
INSERT INTO `wzry_hero` VALUES (8, '妲己', '魅惑之狐', '法师', '中路', 3, 8888, 388, '妲', NULL, '被动·失心：技能命中降低目标法抗\n一技能·灵魂冲击：直线范围伤害\n二技能·偶像魅力：眩晕单个目标\n三技能·女王崇拜：五团狐火追踪伤害', '秘法之靴、回响之杖、痛苦面具、博学者之怒、虚无法杖、贤者之书', '梦魇 + 心眼 + 狩猎（法穿流）', '二技能先手控制，接一三技能秒脆皮；自身较脆，多借草丛蹲人。', '2026-09-04 14:19:35');
INSERT INTO `wzry_hero` VALUES (9, '王昭君', '冰雪之华', '法师', '中路', 4, 8888, 388, '王', NULL, '被动·冰封之心：技能命中冻结目标并增伤\n一技能·凋零冰晶：范围伤害并减速\n二技能·禁锢寒霜：延迟禁锢范围内敌人\n三技能·凛冬已至：大范围持续伤害并减速', '秘法之靴、回响之杖、痛苦面具、博学者之怒、虚无法杖、辉月', '梦魇 + 心眼 + 狩猎', '二技能预判禁锢是关键，命中后衔接大招打满伤害；配合队友控场效果极佳。', '2026-09-04 14:19:35');
INSERT INTO `wzry_hero` VALUES (10, '安琪拉', '魔法少女', '法师', '中路', 3, 8888, 388, '安', NULL, '被动·咒术火焰：技能命中叠加灼烧伤害\n一技能·火球术：直线穿透伤害\n二技能·混沌火种：抛出火种眩晕并减速\n三技能·炽热辉光：持续激光并获护盾与霸体', '秘法之靴、回响之杖、痛苦面具、博学者之怒、虚无法杖、贤者之书', '梦魇 + 心眼 + 狩猎', '二技能命中后一三技能一套秒人；大招期间霸体但无法移动，注意站位。', '2026-09-04 14:19:35');
INSERT INTO `wzry_hero` VALUES (11, '貂蝉', '绝世舞姬', '法师', '中路', 7, 13888, 588, '貂', NULL, '被动·语·花印：技能命中叠加印记，引爆回血并减速\n一技能·落·红雨：抛出花球往返伤害\n二技能·缘·心结：位移并留下花球\n三技能·绽·风华：范围内技能冷却大幅缩减', '秘法之靴、噬神之书、痛苦面具、极寒风暴、虚无法杖、辉月', '梦魇 + 心眼 + 贪婪（法术吸血流）', '大招内靠冷却缩减无限连招，二技能躲避关键控制；吸血是续航核心。', '2026-09-04 14:19:35');
INSERT INTO `wzry_hero` VALUES (12, '后羿', '精灵射手', '射手', '发育路', 2, 5888, 288, '后', NULL, '被动·迟缓之箭：普攻减速并叠加攻速\n一技能·多重箭矢：普攻分裂多支箭\n二技能·燎原箭雨：范围伤害并减速\n三技能·惩戒射击：远程眩晕控制的火焰箭', '急速战靴、末世、无尽战刃、破晓、泣血之刃、逐日之弓', '红月 + 鹰眼 + 狩猎（攻速流）', '站桩输出核心，需辅助保护；大招可远程开团或自保，注意走位躲刺客。', '2026-09-04 14:19:35');
INSERT INTO `wzry_hero` VALUES (13, '鲁班七号', '机关小子', '射手', '发育路', 3, 8888, 388, '鲁', NULL, '被动·火力压制：第五次普攻变为扫射\n一技能·河豚手雷：范围伤害并眩晕\n二技能·无敌鲨嘴炮：全图范围击退\n三技能·空中支援：范围持续轰炸', '急速战靴、末世、无尽战刃、破晓、泣血之刃、纯净苍穹', '红月 + 鹰眼 + 狩猎', '被动扫射打坦快；二技能可远程抢龙或打断，站位要靠后由队友保护。', '2026-09-04 14:19:35');
