INSERT INTO `wzry_hero` VALUES (18, '瑶', '森之精灵', '辅助', '游走', 4, 8888, 388, '瑶', NULL, '被动·山鬼·白鹿：被控后变鹿脱离并减冷却\n一技能·若有人兮：抛出技能探视野并减速\n二技能·风飒木萧：范围持续伤害\n三技能·独立兮山之上：附身队友提供护盾并可主动脱离', '疾步之靴、极影、圣杯、极寒风暴、魔女斗篷、贤者的庇护', '宿命 + 虚空 + 调和', '附身核心输出提供护盾与增益，被集火时主动脱离变鹿逃生；一技能可探草丛。', '2026-09-04 14:19:35');
