INSERT INTO `wzry_hero` VALUES (24, '澜', '鲨之猎刃', '刺客', '打野', 7, 18888, 688, '澜', NULL, '被动·狩猎：对残血敌人造成额外伤害，水下获得加速\n一技能·破浪：水下潜水，地面向前斩击\n二技能·断空：二技能命中标记目标，可两次强化普攻\n三技能·孤猎：投掷鲨鱼，拖拽敌人撞击墙体眩晕', '追击刀锋、抵抗之靴、暗影战斧、破军、碎星锤、名刀·司命', '异变 + 鹰眼 + 狩猎', '利用河道潜水机动，二技能打标记连续输出，大招推墙控住关键C位。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (25, '娜可露露', '鹰之守护', '刺客', '打野', 6, 13888, 588, '娜', NULL, '被动·流刀舞术：技能后强化普攻\n一技能·飞鹰攻击：标记目标，后续伤害百分比扣血\n二技能·风之刃：突进命中回血\n三技能·飞鹰急袭：俯冲落地高额范围伤害', '追击刀锋、抵抗之靴、暗影战斧、破军、碎星锤、名刀·司命', '异变 + 鹰眼 + 狩猎', '大招落地接一技能标记，强化普攻打爆发；身板脆避免被集火。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (26, '镜', '破镜之刃', '刺客', '打野', 9, 18888, 688, '镜', NULL, '被动·铸镜：技能和镜像命中刷新小技能冷却\n一技能·开锋：向前斩击生成镜像\n二技能·裂空：旋转伤害回血\n三技能·见影：生成镜像空间，换位，镜像同步本体技能', '追击刀锋、抵抗之靴、暗影战斧、破军、碎星锤、名刀·司命', '异变 + 鹰眼 + 狩猎', '大招空间内换位打输出拉扯，多利用镜像刷新技能，操作难度很高。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (27, '司马懿', '寂灭之心', '刺客', '中路', 7, 13888, 588, '司', NULL, '被动·静默之语：获得法术伤害转化为普攻，可吸收灵体获取能量\n一技能·幽影之咬：灵体突进，本体留在原地\n二技能·荒芜之域：沉默周围敌人\n三技能·死神降临：远距离俯冲砸击', '急速战靴、巫术法杖、噬神之书、博学者之怒、虚无法杖、辉月', '梦魇 + 心眼 + 狩猎', '一技能灵体探路，二技能沉默打断施法，大招远距离突进切后排。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (28, '不知火舞', '明媚烈焰', '法师', '中路', 8, 13888, 588, '火', NULL, '被动·忍蜂：技能后可以翻滚位移\n一技能·飞翔龙炎阵：向上击飞敌人\n二技能·花蝶扇：远程消耗减速降低法抗\n三技能·必杀·忍蜂：长距离突进击退敌人', '抵抗之靴、回响之杖、痛苦面具、博学者之怒、虚无法杖、辉月', '梦魇 + 心眼 + 狩猎', '被动翻滚灵活拉扯，二技能消耗减魔抗，大招一技能进场打控制爆发。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (29, '高渐离', '叛逆吟游', '法师', '中路', 5, 13888, 588, '高', NULL, '被动·哀歌：第四次普攻额外魔法伤害\n一技能·狂歌：音符弹射伤害\n二技能·离歌：范围伤害减速\n三技能·魔音贯耳：获得加速减伤，持续范围伤害', '抵抗之靴、噬神之书、痛苦面具、博学者之怒、虚无法杖、辉月', '梦魇 + 心眼 + 狩猎', '大招开启冲进人群打AOE爆发，尽量多命中敌方英雄提升生存。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (30, '嬴政', '王者独尊', '法师', '中路', 5, 13888, 688, '嬴', NULL, '被动·王者审判：普攻穿透法术伤害\n一技能·王者惩戒：范围伤害减速\n二技能·王者守御：增加法强移速\n三技能·至尊王权：远程持续飞剑扫射', '秘法之靴、回响之杖、痛苦面具、博学者之怒、虚无法杖、贤者之书', '梦魇 + 心眼 + 狩猎', '大招远程持续输出，利用一技能防守清线，注意保护自身位置。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (31, '小乔', '恋之微风', '法师', '中路', 4, 5888, 288, '乔', NULL, '被动·治愈微笑：技能命中提升移速\n一技能·绽放之舞：扇子往返伤害\n二技能·甜蜜恋风：范围击飞敌人\n三技能·星华缭乱：周围落下流星高额伤害', '秘法之靴、回响之杖、痛苦面具、博学者之怒、虚无法杖、辉月', '梦魇 + 心眼 + 狩猎', '二技能击飞控制，接一三技能打爆发，命中后加速方便拉扯走位。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (32, '干将莫邪', '淬命双剑', '法师', '中路', 8, 13888, 588, '干', NULL, '被动·嗜杀剑气：技能叠加法强\n一技能·护主邪冢：击退近身敌人，位移\n二技能·雌雄双剑·近：近距离飞剑伤害\n三技能·雌雄双剑·远：远距离飞剑伤害\n四技能·剑来：强化二三技能飞剑数量', '秘法之靴、回响之杖、痛苦面具、博学者之怒、虚无法杖、辉月', '梦魇 + 心眼 + 狩猎', '靠飞剑远程消耗输出，一技能推开贴脸刺客，大招强化提升爆发。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (33, '蒙犽', '烈炮小子', '射手', '发育路', 5, 13888, 588, '蒙', NULL, '被动·炽烈浑天：技能叠加怒气，满怒强化伤害回血\n一技能·狂轰火线：持续扫射伤害\n二技能·爆裂重炮：炮弹分裂减速\n三技能·飞弹援袭：远距离导弹支援输出', '急速战靴、暗影战斧、无尽战刃、破晓、泣血之刃、纯净苍穹', '红月 + 鹰眼 + 狩猎', '一技能持续扫射输出，大招远程支援团战，注意怒气状态，怕近身。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (34, '马可波罗', '远游之枪', '射手', '发育路', 6, 13888, 588, '马', NULL, '被动·连锁反应：普攻技能叠加印记，满层触发真实伤害\n一技能·华丽左轮：连续子弹扫射\n二技能·漫游之枪：位移\n三技能·狂热弹幕：旋转范围真实伤害', '急速战靴、末世、纯净苍穹、破晓、魔女斗篷、名刀·司命', '红月 + 鹰眼 + 狩猎', '叠满被动触发真实伤害，大招进场要谨慎，二技能留作保命位移。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (35, '伽罗', '破魔之箭', '射手', '发育路', 4, 13888, 588, '伽', NULL, '被动·破魔之箭：对护盾造成额外伤害\n一技能·渡厄之箭：开启增加射程消耗蓝量\n二技能·静默之箭：远程伤害减速沉默\n三技能·纯净之域：范围暴击加速增益', '急速战靴、末世、无尽战刃、破晓、泣血之刃、逐日之弓', '红月 + 鹰眼 + 狩猎', '一技能远程消耗，二技能沉默打断敌人，自身没有位移极度依赖保护。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (36, '李元芳', '王都密探', '射手', '打野', 5, 13888, 588, '元', NULL, '被动·密探谛听：获得周围敌人视野\n一技能·飞镖·谍影：标记目标，爆炸伤害\n二技能·刃遁：位移留下路径伤害\n三技能·无间风刃：飞轮持续范围伤害减速', '追击刀锋、急速战靴、末世、无尽战刃、破晓、名刀·司命', '红月 + 鹰眼 + 狩猎', '被动探测草丛防埋伏，一技能打标记爆发，大招封路，可快速打龙。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (37, '苏烈', '不屈铁壁', '坦克', '游走', 4, 13888, 588, '苏', NULL, '被动·不屈铁壁：死亡不会立刻阵亡，队友点亮烽火复活\n一技能·烽烟踏破：强化三次普攻最后一击击飞\n二技能·所向披靡：蓄力冲撞击退敌人\n三技能·豪烈万军：蓄力砸地大范围击飞', '抵抗之靴、红莲斗篷、极寒风暴、魔女斗篷、不祥征兆、霸者重装', '宿命 + 虚空 + 调和', '被动可以复活，大招蓄力大范围开团，二技能推人分割敌方阵型。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (38, '东皇太一', '噬灭日蚀', '坦克', '游走', 4, 13888, 588, '东', NULL, '被动·暗冕之噬：环绕黑球触碰敌人吸血\n一技能·日曜龙烛：生成黑球\n二技能·曜龙烛兆：黑球释放范围伤害减速\n三技能·堕神契约：压制敌方英雄互相受到伤害', '抵抗之靴、红莲斗篷、极寒风暴、魔女斗篷、不祥征兆、霸者重装', '宿命 + 虚空 + 调和', '贴身靠黑球吸血，大招强制压制敌方关键输出，咬住不要轻易松开。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (39, '钟馗', '虚灵城判', '坦克', '游走', 5, 13888, 588, '钟', NULL, '被动·制裁仪式：死亡爆炸伤害，受击获得护盾\n一技能·虚空清道者：范围伤害减速\n二技能·湮灭之锁：钩子把敌人拉到身前\n三技能·轮回吞噬：持续眩晕周围敌人', '抵抗之靴、红莲斗篷、极寒风暴、魔女斗篷、不祥征兆、贤者的庇护', '宿命 + 虚空 + 调和', '二技能钩子是灵魂，勾住敌方C位；钩空之后自身很容易被反打。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (40, '盾山', '无尽之盾', '坦克', '游走', 4, 13888, 588, '盾', NULL, '被动·天地化盾：举盾格挡飞行攻击\n一技能·一夫当关：举起巨盾阻挡弹道\n二技能·万夫莫开：把敌人背摔扔到身后\n三技能·不动如山：落地巨盾无法移动，阻挡敌人前进\n四技能·困守成规：修复防御塔血量', '抵抗之靴、红莲斗篷、极寒风暴、魔女斗篷、不祥征兆、霸者重装', '宿命 + 虚空 + 调和', '一技能挡大量飞行技能，二技能背摔开团，可以修理防御塔。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (41, '明世隐', '占星师', '辅助', '游走', 3, 13888, 588, '明', NULL, '被动·大吉大利：普攻三次眩晕敌人\n一技能·临卦·无忧：链子连接队友增益，连接敌人减益\n二技能·师卦·飞翼：切换链子攻防属性\n三技能·乾卦·飞龙：对连接目标造成高额真实伤害或大量回血', '疾步之靴、极影、圣杯、极寒风暴、魔女斗篷、贤者的庇护', '宿命 + 虚空 + 调和', '链子牢牢连己方核心输出，大招可以给队友抬血或者斩杀残血敌人。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (42, '大乔', '海之新娘', '辅助', '游走', 5, 13888, 588, '乔', NULL, '被动·川流不息：给附近队友增加移速\n一技能·鲤跃之潮：推击击飞敌人\n二技能·宿命之海：召唤法阵，回城并且补满状态\n三技能·绝断之桥：沉默范围内敌人\n四技能·旋涡之门：召唤传送阵召集全体队友', '疾步之靴、极影、圣杯、极寒风暴、魔女斗篷、贤者的庇护', '宿命 + 虚空 + 调和', '二技能快速回城补给，大招召集队友打团战，一三技能提供控制。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (43, '廉颇', '正义爆轰', '坦克', '对抗路', 4, 8888, 388, '廉', NULL, '被动·勇士之魂：释放技能全程霸体获得减伤\n一技能·爆裂冲撞：向前撞击击飞敌人\n二技能·熔岩重击：蓄力范围伤害减速\n三技能·天崩地裂：连续砸地多次击飞', '抵抗之靴、红莲斗篷、极寒风暴、魔女斗篷、不祥征兆、霸者重装', '宿命 + 虚空 + 调和', '技能全程霸体不怕控制，大招连续击飞，适合先手开团抗伤害。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (44, '芈月', '永恒之月', '法师', '对抗路', 5, 13888, 588, '芈', NULL, '被动·永生之血：释放技能召唤暗影仆从自动攻击吸血\n一技能·痛苦冲击：位移，可以二次回到释放位置\n二技能·幻翼仆从：链子连接敌人吸取法强\n三技能·暗影之月：无法选中状态，免疫伤害', '抵抗之靴、噬神之书、痛苦面具、极寒风暴、虚无法杖、辉月', '梦魇 + 心眼 + 贪婪', '二技能链接目标偷取属性，大招用来躲避致命伤害，靠仆从持续吸血。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (45, '李信', '谋世之战', '战士', '对抗路', 7, 13888, 588, '信', NULL, '被动·灰暗利刃：形态切换，分未觉醒、统御、狂暴形态\n一技能·急速突进/迅烈之华：光形态远程消耗，暗形态突进回血\n二技能·强力斩击/狂啸利刃：光形态远程剑气，暗形态强化普攻\n三技能·力量觉醒·光/力量觉醒·暗：切换光信远程或暗信偷带牵制', '抵抗之靴、暗影战斧、末世、碎星锤、魔女斗篷、名刀·司命', '异变 + 鹰眼 + 狩猎', '光信远程消耗打团；暗信带线偷塔牵制，灵活选择作战形态。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (46, '元歌', '无间傀儡', '刺客', '中路', 10, 13888, 588, '元', NULL, '被动·秘术·操控：拥有本体和傀儡两套技能\n一技能·秘术·影：放出傀儡作战\n二技能·秘术·纸雏鸾：本体远程伤害\n三技能·秘术·十字闪：傀儡控制伤害\n四技能·秘术·归：傀儡收回本体，位移', '冷静之靴、暗影战斧、破军、碎星锤、名刀·司命、辉月', '异变 + 鹰眼 + 狩猎', '傀儡负责探视野、打控制，本体注意隐藏，傀儡阵亡本体进入虚弱。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (47, '钟无艳', '野蛮之锤', '战士', '对抗路', 4, 5888, 288, '钟', NULL, '被动·石之炼金：技能命中概率石化敌人\n一技能·狂飙突进：突进强化普攻\n二技能·震慑打击：中心区域双倍伤害\n三技能·飓风之锤：持续旋转范围伤害', '抵抗之靴、暗影战斧、极寒风暴、破军、魔女斗篷、贤者的庇护', '异变 + 鹰眼 + 狩猎', '被动石化随机控制，二技能中心打高额爆发，大招持续输出骚扰。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (48, '夏侯惇', '不羁之风', '坦克', '对抗路', 4, 13888, 588, '夏', NULL, '被动·噬目：血量低时普攻技能回血\n一技能·豪气斩：第一段伤害，第二段击飞\n二技能·龙卷闪：获得护盾强化普攻真实伤害\n三技能·不羁之刃：钩子位移撞击眩晕敌人', '抵抗之靴、红莲斗篷、极寒风暴、魔女斗篷、不祥征兆、霸者重装', '宿命 + 虚空 + 调和', '被动残血回血提升续航，大招远距离位移开团，能抗能打。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (49, '白起', '最终兵器', '坦克', '对抗路', 5, 13888, 588, '白', NULL, '被动·反击之镰：受伤叠加能量提升伤害回血\n一技能·血之回响：旋转伤害命中回血\n二技能·死神之镰：钩住敌人拉扯\n三技能·死神降临：嘲讽大范围敌人强制攻击自己', '抵抗之靴、红莲斗篷、极寒风暴、魔女斗篷、不祥征兆、霸者重装', '宿命 + 虚空 + 调和', '大招群体嘲讽强制吸火力，二技能把敌人拉进战场，叠被动提升坦度。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (50, '扁鹊', '善恶怪医', '法师', '中路', 4, 5888, 288, '扁', NULL, '被动·恶德医疗：技能普攻叠加印记，持续毒伤或治疗\n一技能·致命灵药：投放药瓶持续区域伤害\n二技能·善恶诊断：向前药剂伤害，治疗周围友军\n三技能·生命主宰：引爆印记，高额伤害或群体治疗', '抵抗之靴、噬神之书、痛苦面具、极寒风暴、虚无法杖、魔女斗篷', '梦魇 + 心眼 + 贪婪', '持续叠加印记，大招引爆打伤害或者抬团队血量，打持续消耗战。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (51, '姜子牙', '太古魔导', '法师', '游走', 4, 8888, 388, '姜', NULL, '被动·心魔：给队友额外经验加速等级\n一技能·忏悔：持续减速减双抗\n二技能·湮灭：爆炸击飞\n三技能·断罪：超远蓄力远程激光输出', '疾步之靴、回响之杖、痛苦面具、博学者之怒、虚无法杖、辉月', '梦魇 + 心眼 + 狩猎', '被动帮助队友快速升级，大招远程消耗压血线，二技能击飞保护自己。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (52, '裴擒虎', '六合虎拳', '刺客', '打野', 8, 13888, 588, '裴', NULL, '被动·寸劲/虎啸：人形态远程，虎形态近战\n一技能·冲拳式/虎啸风生：人形态伤害减速，虎形态跳跃\n二技能·气守式/虎跃式：人形态护盾加速，虎形态折返跳跃\n三技能·虎形切换：人虎两种形态自由切换', '追击刀锋、抵抗之靴、暗影战斧、末世、碎星锤、名刀·司命', '异变 + 鹰眼 + 狩猎', '双形态，人形态消耗，虎形态近身爆发，前期入侵野区能力极强。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (53, '云中君', '流云之翼', '刺客', '打野', 7, 13888, 588, '云', NULL, '被动·云间游：飞行状态无视地形，普攻撕裂流血\n一技能·天隙鸣：俯冲撞击击飞\n二技能·若英·华彩：弹开敌方控制\n三技能·风雷引：升空俯冲落地伤害', '追击刀锋、急速战靴、暗影战斧、无尽战刃、泣血之刃、名刀·司命', '异变 + 鹰眼 + 狩猎', '飞行无视地形游走支援，二技能弹控保命，撕裂流血持续输出。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (54, '杨戬', '根源之目', '战士', '对抗路', 5, 13888, 588, '杨', NULL, '被动·神智侵蚀：减少受到控制时长\n一技能·逆转乾坤：放出哮天犬标记目标，可以再次突进扑杀\n二技能·虚妄破灭：横扫命中残血敌人眩晕\n三技能·根源之目：三道激光伤害并且回血', '抵抗之靴、暗影战斧、极寒风暴、破军、魔女斗篷、贤者的庇护', '异变 + 鹰眼 + 狩猎', '一技能标记追击收割，二技能眩晕敌人，大招多段激光高额吸血续航。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (55, '哪吒', '桀骜炎枪', '战士', '对抗路', 5, 13888, 588, '哪', NULL, '被动·炙炼火种：普攻技能附加持续灼烧，限制回血\n一技能·火焰三尖枪：挥枪伤害加速\n二技能·混天绫·束：圈住敌人减伤\n三技能·乾坤·天降：锁定全图一名敌人俯冲追击', '抵抗之靴、红莲斗篷、暗影战斧、不祥征兆、魔女斗篷、贤者的庇护', '异变 + 鹰眼 + 调和', '大招全图飞针对敌方后排，被动克制回血英雄，二技能减伤保命。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (56, '沈梦溪', '爆弹怪猫', '法师', '中路', 5, 13888, 588, '沈', NULL, '被动·暴躁节奏：技能命中敌人获得炸弹\n一技能·猫咪炸弹：投掷炸弹消耗\n二技能·正常操作：给自己加速，下颗炸弹变为范围眩晕\n三技能·综合爆款：超远大范围轰炸', '秘法之靴、回响之杖、痛苦面具、博学者之怒、虚无法杖、辉月', '梦魇 + 心眼 + 狩猎', '二技能眩晕控场，大招远距离大范围消耗压血线，清线支援速度快。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (57, '上官婉儿', '惊鸿之笔', '法师', '中路', 9, 13888, 588, '婉', NULL, '被动·笔阵：技能触发强化普攻\n一技能·篆法·疾势：笔墨向前伤害\n二技能·飞白·藏锋：笔墨向后伤害\n三技能·章草·横鳞：触碰笔墨多次完成飞天，无法选中打多段伤害', '秘法之靴、回响之杖、痛苦面具、博学者之怒、虚无法杖、辉月', '梦魇 + 心眼 + 狩猎', '利用一二技能笔墨完成大招飞天，飞天期间不可选中切后排，需要练习连招。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (58, '百里守约', '静谧之眼', '射手', '发育路', 5, 13888, 588, '约', NULL, '被动·瞄准：贴墙进入伪装状态，普攻高额伤害\n一技能·静谧之眼：放置视野装置\n二技能·绝影神枪：蓄力超远狙击\n三技能·逃脱：向后位移射击', '急速战靴、暗影战斧、无尽战刃、破晓、泣血之刃、名刀·司命', '异变 + 鹰眼 + 狩猎', '一技能布置视野，二技能远程狙击消耗，三技能位移保命，近距离普攻输出。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (59, '百里玄策', '嚣狂之镰', '刺客', '打野', 8, 13888, 588, '策', NULL, '被动·狂热序章：击杀助攻大幅提升攻速移速\n一技能·神乎钩镰：位移，钩中拉扯敌人\n二技能·梦魇钩锁：甩出飞镰钩住目标\n三技能·瞬镰闪：钩中目标可以穿过敌人造成伤害', '追击刀锋、急速战靴、暗影战斧、无尽战刃、泣血之刃、名刀·司命', '异变 + 鹰眼 + 狩猎', '二技能钩子命中是核心，钩住之后拉扯敌人，击杀后利用被动疯狂收割。', '2026-09-04 14:58:47');
INSERT INTO `wzry_hero` VALUES (60, '西施', '幻纱之灵', '法师', '中路', 6, 13888, 588, '施', NULL, '被动·纱灵庇护：距离远降低受到伤害\n一技能·纱缚之印：能量球命中牵引敌人移动\n二技能·幻纱之灵：多段法球伤害\n三技能·心无旁骛：强化一技能，可以连续拉扯敌人两次', '秘法之靴、回响之杖、痛苦面具、博学者之怒、虚无法杖、辉月', '梦魇 + 心眼 + 狩猎', '一技能强制拉扯敌人改变位置，大招强化控制，拉扯打乱敌方阵型。', '2026-09-04 14:58:47');
